function tableHas(table: number[][], target: number): boolean {
  for (const row of table) {
    if (row[0] > target || row[row.length - 1] < target) continue;
    let lo = 0, hi = row.length - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (row[mid] === target) return true;
      if (row[mid] < target) lo = mid + 1; else hi = mid - 1;
    }
  }
  return false;
}

