function tableHas(table: number[][], target: number): boolean {
  let row = 0, col = table[0].length - 1;
  while (row < table.length && col >= 0) {
    const v = table[row][col];
    if (v === target) return true;
    if (v > target) col--; // everything below is bigger still
    else row++;            // everything to the left is smaller still
  }
  return false;
}

